SET ROLE postgres;
UPDATE sop_articles
SET content = E'<p>Před odjezdem na dovolenou je klíčové zajistit, aby tvoje absence co nejméně ovlivnila chod projektů a spokojenost klientů. Dobrá příprava umožní týmu hladce pokračovat v práci, minimalizuje stres z nenadálých situací a zároveň ti poskytne klidnou dovolenou bez nutnosti řešit problémy na dálku.</p>\n<h2>Checklist: Co udělat před odjezdem na dovolenou</h2>\n<h3>1. Informuj nadřízené a kolegy</h3>\n<p>Napiš do Slack kanálu <strong>#scls_dovolena</strong> termíny dovolené a jméno svého zástupce.</p>\n<h3>2. Informuj klienta</h3>\n<ul>\n<li><p>Domluv se s klientem, aby se co nejvíce práce stihlo před odjezdem.</p></li>\n<li><p>Sděl mu, kdo tě bude zastupovat, a ujisti se, že ví, jak zástupce kontaktovat přes Freelo.</p></li>\n</ul>\n<h3>3. Domluv zástupce</h3>\n<p>Urči kolegu, který tě bude zastupovat, a dej mu všechny potřebné informace o projektech a úkolech.</p>\n<h3>4. Připrav Freelo</h3>\n<ul>\n<li><p>Aktualizuj všechny rozpracované úkoly ve Freelu.</p></li>\n<li><p>Označ zástupce jako odpovědnou osobu tam, kde je to potřeba.</p></li>\n</ul>\n<h3>5. Nastav automatickou odpověď na e-mailu</h3>\n<p><strong>Šablona: Automatická odpověď během dovolené</strong></p>\n<p><strong>Předmět:</strong> Automatická odpověď: Děkuji za váš e-mail, nyní jsem na dovolené</p>\n<p>Dobrý den,</p>\n<p>děkuji za váš e-mail. Momentálně jsem na dovolené do <strong>[vložit datum konce]</strong>.</p>\n<p>Pokud je váš požadavek urgentní, prosím, kontaktujte mého kolegu, který mě během mé nepřítomnosti zastupuje:</p>\n<ul>\n<li><p><strong>[Jméno zastupujícího kolegy]</strong></p></li>\n<li><p>E-mail: <strong>[e-mailová adresa]</strong></p></li>\n</ul>\n<p>Vašemu e-mailu se budu věnovat ihned po návratu.</p>\n<p>Děkuji za pochopení a přeji krásný den!</p>\n<h3>Návod: Jak nastavit automatickou odpověď v Gmailu</h3>\n<ol>\n<li><p><strong>Přihlaste se do Gmailu</strong> - Otevřete Gmail na počítači.</p></li>\n<li><p><strong>Otevřete nastavení</strong> - Klikněte na ikonu ozubeného kolečka a vyberte „Zobrazit všechna nastavení".</p></li>\n<li><p><strong>Najděte sekci „Automatická odpověď"</strong> - Přepněte na kartu „Obecné" a posuňte se dolů.</p></li>\n<li><p><strong>Zapněte automatickou odpověď</strong> - Klikněte na „Automatická odpověď zapnuta".</p></li>\n<li><p><strong>Vyplňte podrobnosti</strong> - Zadejte datum začátku/konce a zkopírujte šablonu výše.</p></li>\n<li><p><strong>Uložte změny</strong> - Klikněte na „Uložit změny" ve spodní části stránky.</p></li>\n</ol>\n<h3>6. Sdílej fotky z dovolené!</h3>\n<p>Pošli do Slack kanálu fotky a inspiruj kolegy na příští dovolenou.</p>\n<p>S tímto postupem si užiješ klidnou dovolenou a tvůj tým bude mít všechno pod kontrolou.</p>'
WHERE id = 'e6ee3aec-e1cf-439c-8e3b-8eecd74be6f1';
